package main

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
	"github.com/sirupsen/logrus"
	logrustest "github.com/sirupsen/logrus/hooks/test"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// respondError 是全仓库共用的错误出口。分级只是一行 if，改回去编译和其他单测
// 都不会报错，但鉴权开启后被扫描器打的 401 会重新刷满 ERROR。
func TestRespondErrorLogLevel(t *testing.T) {
	tests := []struct {
		name       string
		statusCode int
		wantLevel  logrus.Level
	}{
		{name: "401 记为 warning", statusCode: http.StatusUnauthorized, wantLevel: logrus.WarnLevel},
		{name: "400 记为 warning", statusCode: http.StatusBadRequest, wantLevel: logrus.WarnLevel},
		{name: "500 记为 error", statusCode: http.StatusInternalServerError, wantLevel: logrus.ErrorLevel},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			hook := logrustest.NewGlobal()
			defer hook.Reset()

			gin.SetMode(gin.TestMode)
			c, _ := gin.CreateTestContext(httptest.NewRecorder())
			c.Request = httptest.NewRequest(http.MethodGet, "/api/v1/login/status", nil)

			respondError(c, tt.statusCode, "CODE", "消息", nil)

			require.Len(t, hook.Entries, 1)
			assert.Equal(t, tt.wantLevel, hook.LastEntry().Level)
		})
	}
}

package configs

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

// TestFingerprintSeedFromEnv 校验 XHS_FP_SEED 解析：非法/非正数一律回退 0（随机）。
func TestFingerprintSeedFromEnv(t *testing.T) {
	tests := []struct {
		name string
		env  string
		want int
	}{
		{name: "未设返回0", env: "", want: 0},
		{name: "合法seed", env: "98759", want: 98759},
		{name: "非数字回退0", env: "abc", want: 0},
		{name: "零回退0", env: "0", want: 0},
		{name: "负数回退0", env: "-5", want: 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Setenv("XHS_FP_SEED", tt.env)
			assert.Equal(t, tt.want, FingerprintSeedFromEnv())
		})
	}
}

func TestProxyFromEnv(t *testing.T) {
	t.Run("未设为空", func(t *testing.T) {
		t.Setenv("XHS_PROXY", "")
		assert.Equal(t, "", ProxyFromEnv())
	})
	t.Run("读取代理地址", func(t *testing.T) {
		t.Setenv("XHS_PROXY", "socks5://127.0.0.1:1080")
		assert.Equal(t, "socks5://127.0.0.1:1080", ProxyFromEnv())
	})
}

package browser

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

// TestMaskProxyCredentials 校验代理日志脱敏：绝不能把用户名/密码打进日志。
func TestMaskProxyCredentials(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{name: "空字符串", input: "", want: ""},
		{name: "无认证信息原样返回", input: "http://127.0.0.1:8080", want: "http://127.0.0.1:8080"},
		{name: "用户名+密码都脱敏", input: "http://user:pass@host:8080", want: "http://***:***@host:8080"},
		{name: "仅用户名脱敏", input: "http://user@host:8080", want: "http://***@host:8080"},
		{name: "socks5带认证", input: "socks5://alice:secret@127.0.0.1:1080", want: "socks5://***:***@127.0.0.1:1080"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.want, maskProxyCredentials(tt.input))
		})
	}
}

// TestOptions 校验 Option 正确写入 browserConfig（New+Option 的接线）。
func TestOptions(t *testing.T) {
	cfg := &browserConfig{}
	WithFingerprintSeed(98759)(cfg)
	WithProxy("http://127.0.0.1:8080")(cfg)

	assert.Equal(t, 98759, cfg.fingerprintSeed)
	assert.Equal(t, "http://127.0.0.1:8080", cfg.proxy)
}

// TestOptions_Defaults 未传 Option 时各字段为零值（回退随机 seed / 不设代理）。
func TestOptions_Defaults(t *testing.T) {
	cfg := &browserConfig{}
	assert.Equal(t, 0, cfg.fingerprintSeed)
	assert.Equal(t, "", cfg.proxy)
}

//go:build integration

// 集成测试：起有头浏览器 + 触网 + 需登录态，默认 go test 不编译不运行。
// 手动跑：go test -tags integration ./xiaohongshu/ -run TestSearch
package xiaohongshu

import (
	"context"
	"fmt"
	"testing"

	"github.com/stretchr/testify/require"
	"github.com/xpzouying/xiaohongshu-mcp/browser"
)

func TestSearch(t *testing.T) {
	b := browser.NewBrowser(false)
	defer b.Close()

	page := b.NewPage()
	defer func() {
		_ = page.Close()
	}()

	action := NewSearchAction(page)

	feeds, err := action.Search(context.Background(), "Kimi")
	require.NoError(t, err)
	require.NotEmpty(t, feeds, "feeds should not be empty")

	fmt.Printf("成功获取到 %d 个 Feed\n", len(feeds))

	for _, feed := range feeds {
		fmt.Printf("Feed ID: %s\n", feed.ID)
		fmt.Printf("Feed Title: %s\n", feed.NoteCard.DisplayTitle)
	}
}

func TestSearchWithFilters(t *testing.T) {
	b := browser.NewBrowser(false)
	defer b.Close()

	page := b.NewPage()
	defer func() {
		_ = page.Close()
	}()

	action := NewSearchAction(page)

	filter := FilterOption{
		SortBy:      "最新",
		NoteType:    "不限",
		PublishTime: "半年内",
		SearchScope: "不限",
		Location:    "不限",
	}

	feeds, err := action.Search(context.Background(), "无锡 夏天 遛娃 凉快 户外", filter)
	require.NoError(t, err)
	require.NotEmpty(t, feeds, "feeds should not be empty")

	fmt.Printf("成功获取到 %d 个筛选后的 Feed\n", len(feeds))

	for _, feed := range feeds {
		fmt.Printf("Feed ID: %s\n", feed.ID)
		fmt.Printf("Feed Title: %s\n", feed.NoteCard.DisplayTitle)
	}
}

// 同文本多节点时，只应取可见的那个。
func TestFindFilterOptionPicksVisibleOption(t *testing.T) {
	b := browser.NewBrowser(true)
	defer b.Close()

	page := b.NewPage()
	defer func() {
		_ = page.Close()
	}()

	cases := []struct {
		name  string
		style string
	}{
		{"display", `display: none`},
		{"visibility", `visibility: hidden`},
		{"opacity", `opacity: 0.001`},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			page.MustSetDocumentContent(fmt.Sprintf(`<div class="filter-panel">
				<div class="filters">
					<span>笔记类型</span>
					<div id="skip" class="tags" style="width: 80px; height: 24px; %s">图文</div>
					<div id="want" class="tags" style="width: 80px; height: 24px">图文</div>
				</div>
			</div>`, c.style))

			option, err := findFilterOption(page, pendingFilter{group: "笔记类型", option: "图文"})
			require.NoError(t, err)
			id, err := option.Attribute("id")
			require.NoError(t, err)
			require.NotNil(t, id)
			require.Equal(t, "want", *id)
		})
	}
}

// 祖先透明时，子节点自报的 opacity 不作数。
func TestFindFilterOptionChecksAncestorOpacity(t *testing.T) {
	b := browser.NewBrowser(true)
	defer b.Close()

	page := b.NewPage()
	defer func() {
		_ = page.Close()
	}()

	page.MustSetDocumentContent(`<div class="filter-panel">
		<div class="filters">
			<span>笔记类型</span>
			<div style="opacity: 0.001">
				<div id="skip" class="tags" style="width: 80px; height: 24px; opacity: 1">图文</div>
			</div>
			<div id="want" class="tags" style="width: 80px; height: 24px">图文</div>
		</div>
	</div>`)

	option, err := findFilterOption(page, pendingFilter{group: "笔记类型", option: "图文"})
	require.NoError(t, err)
	id, err := option.Attribute("id")
	require.NoError(t, err)
	require.NotNil(t, id)
	require.Equal(t, "want", *id)
}

// 同文本节点全都不可见时要报错，不能退而求其次点一个。
func TestFindFilterOptionRejectsAllInvisible(t *testing.T) {
	b := browser.NewBrowser(true)
	defer b.Close()

	page := b.NewPage()
	defer func() {
		_ = page.Close()
	}()

	page.MustSetDocumentContent(`<div class="filter-panel">
		<div class="filters">
			<span>笔记类型</span>
			<div class="tags" style="opacity: 0.001">图文</div>
			<div class="tags" style="display: none">图文</div>
		</div>
	</div>`)

	_, err := findFilterOption(page, pendingFilter{group: "笔记类型", option: "图文"})
	require.ErrorContains(t, err, "当前不可见")
}

package xiaohongshu

import (
	"testing"

	"github.com/stretchr/testify/require"
)

func TestCollectFilters(t *testing.T) {
	t.Run("只展开非空字段", func(t *testing.T) {
		pending, err := collectFilters([]FilterOption{{
			NoteType:    "图文",
			PublishTime: "一天内",
		}})
		require.NoError(t, err)
		require.Equal(t, []pendingFilter{
			{group: "笔记类型", option: "图文"},
			{group: "发布时间", option: "一天内"},
		}, pending)
	})

	t.Run("五个非默认字段全给", func(t *testing.T) {
		pending, err := collectFilters([]FilterOption{{
			SortBy:      "最新",
			NoteType:    "视频",
			PublishTime: "一周内",
			SearchScope: "已关注",
			Location:    "同城",
		}})
		require.NoError(t, err)
		require.Len(t, pending, 5)
		require.Equal(t, pendingFilter{group: "排序依据", option: "最新"}, pending[0])
		require.Equal(t, pendingFilter{group: "位置距离", option: "同城"}, pending[4])
	})

	t.Run("默认值不需要重复点击", func(t *testing.T) {
		pending, err := collectFilters([]FilterOption{
			{
				SortBy:      "综合",
				NoteType:    "不限",
				PublishTime: "不限",
				SearchScope: "不限",
				Location:    "不限",
			},
		})
		require.NoError(t, err)
		require.Empty(t, pending)
	})

	t.Run("只保留非默认筛选项", func(t *testing.T) {
		pending, err := collectFilters([]FilterOption{
			{
				SortBy:      "最新",
				NoteType:    "不限",
				PublishTime: "半年内",
				SearchScope: "不限",
				Location:    "不限",
			},
		})
		require.NoError(t, err)
		require.Equal(t, []pendingFilter{
			{group: "排序依据", option: "最新"},
			{group: "发布时间", option: "半年内"},
		}, pending)
	})

	t.Run("同组最后一个默认值会清除前面的筛选", func(t *testing.T) {
		pending, err := collectFilters([]FilterOption{
			{NoteType: "图文"},
			{NoteType: "不限"},
		})
		require.NoError(t, err)
		require.Empty(t, pending)
	})

	t.Run("同组最后一个非默认值生效", func(t *testing.T) {
		pending, err := collectFilters([]FilterOption{
			{NoteType: "图文"},
			{NoteType: "视频"},
		})
		require.NoError(t, err)
		require.Equal(t, []pendingFilter{
			{group: "笔记类型", option: "视频"},
		}, pending)
	})

	t.Run("全空则无待应用项", func(t *testing.T) {
		pending, err := collectFilters([]FilterOption{{}})
		require.NoError(t, err)
		require.Empty(t, pending)
	})

	t.Run("非法取值在打开页面之前就报错", func(t *testing.T) {
		_, err := collectFilters([]FilterOption{{NoteType: "不存在的类型"}})
		require.Error(t, err)
		// 错误里要带上可选值，调用方才知道该怎么改
		require.Contains(t, err.Error(), "笔记类型")
		require.Contains(t, err.Error(), "图文")
	})

	t.Run("取值不能跨组", func(t *testing.T) {
		// 「视频」是笔记类型的选项，不能当排序依据
		_, err := collectFilters([]FilterOption{{SortBy: "视频"}})
		require.Error(t, err)
		require.Contains(t, err.Error(), "排序依据")
	})
}

// TestFilterGroupsCoverFilterOption 组表必须覆盖 FilterOption 的每个字段，
// 否则以后新增字段会被静默忽略。
func TestFilterGroupsCoverFilterOption(t *testing.T) {
	all := FilterOption{
		SortBy:      "sort_by",
		NoteType:    "note_type",
		PublishTime: "publish_time",
		SearchScope: "search_scope",
		Location:    "location",
	}

	var picked []string
	for _, g := range filterGroups {
		picked = append(picked, g.pick(all))
	}
	require.ElementsMatch(t, []string{
		"sort_by", "note_type", "publish_time", "search_scope", "location",
	}, picked, "组表漏了 FilterOption 的字段")

	for _, g := range filterGroups {
		require.NotEmpty(t, g.label)
		require.NotEmpty(t, g.defaultValue, "%s 没有默认值", g.label)
		require.NotEmpty(t, g.allowed, "%s 没有合法取值清单", g.label)
		require.Contains(t, g.allowed, g.defaultValue, "%s 的默认值不在合法取值中", g.label)
		require.NotNil(t, g.pick, "%s 没有取值函数", g.label)
	}
}

package main

import (
	"net/http"
	"strconv"

	"github.com/xpzouying/xiaohongshu-mcp/cookies"
	"github.com/xpzouying/xiaohongshu-mcp/xiaohongshu"

	"github.com/gin-gonic/gin"
	"github.com/sirupsen/logrus"
)

// respondError 返回错误响应
func respondError(c *gin.Context, statusCode int, code, message string, details any) {
	response := ErrorResponse{
		Error:   message,
		Code:    code,
		Details: details,
	}

	// 4xx 是调用方传错，5xx 才是服务端故障，用日志级别区分开。
	// 否则鉴权开启后被扫描器打，401 会把 ERROR 刷满。
	if statusCode < http.StatusInternalServerError {
		logrus.Warnf("%s %s %d", c.Request.Method, c.Request.URL.Path, statusCode)
	} else {
		logrus.Errorf("%s %s %d", c.Request.Method, c.Request.URL.Path, statusCode)
	}

	c.JSON(statusCode, response)
}

// respondSuccess 返回成功响应
func respondSuccess(c *gin.Context, data any, message string) {
	response := SuccessResponse{
		Success: true,
		Data:    data,
		Message: message,
	}

	logrus.Infof("%s %s %d", c.Request.Method, c.Request.URL.Path, http.StatusOK)

	c.JSON(http.StatusOK, response)
}

// checkLoginStatusHandler 检查登录状态
func (s *AppServer) checkLoginStatusHandler(c *gin.Context) {
	status, err := s.xiaohongshuService.CheckLoginStatus(c.Request.Context())
	if err != nil {
		respondError(c, http.StatusInternalServerError, "STATUS_CHECK_FAILED",
			"检查登录状态失败", err.Error())
		return
	}

	respondSuccess(c, status, "检查登录状态成功")
}

// getLoginQrcodeHandler 处理 [GET /api/v1/login/qrcode] 请求。
// 用于生成并返回登录二维码（Base64 图片 + 超时时间），供前端展示给用户扫码登录。
func (s *AppServer) getLoginQrcodeHandler(c *gin.Context) {
	result, err := s.xiaohongshuService.GetLoginQrcode(c.Request.Context())
	if err != nil {
		respondError(c, http.StatusInternalServerError, "STATUS_CHECK_FAILED",
			"获取登录二维码失败", err.Error())
		return
	}

	respondSuccess(c, result, "获取登录二维码成功")
}

// deleteCookiesHandler 删除 cookies，重置登录状态
func (s *AppServer) deleteCookiesHandler(c *gin.Context) {
	err := s.xiaohongshuService.DeleteCookies(c.Request.Context())
	if err != nil {
		respondError(c, http.StatusInternalServerError, "DELETE_COOKIES_FAILED",
			"删除 cookies 失败", err.Error())
		return
	}

	cookiePath := cookies.GetCookiesFilePath()
	respondSuccess(c, map[string]interface{}{
		"cookie_path": cookiePath,
		"message":     "Cookies 已成功删除，登录状态已重置。下次操作时需要重新登录。",
	}, "删除 cookies 成功")
}

// publishHandler 发布内容
func (s *AppServer) publishHandler(c *gin.Context) {
	var req PublishRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		respondError(c, http.StatusBadRequest, "INVALID_REQUEST",
			"请求参数错误", err.Error())
		return
	}

	result, err := s.xiaohongshuService.PublishContent(c.Request.Context(), &req)
	if err != nil {
		respondError(c, http.StatusInternalServerError, "PUBLISH_FAILED",
			"发布失败", err.Error())
		return
	}

	respondSuccess(c, result, "发布成功")
}

// publishVideoHandler 发布视频内容
func (s *AppServer) publishVideoHandler(c *gin.Context) {
	var req PublishVideoRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		respondError(c, http.StatusBadRequest, "INVALID_REQUEST",
			"请求参数错误", err.Error())
		return
	}

	result, err := s.xiaohongshuService.PublishVideo(c.Request.Context(), &req)
	if err != nil {
		respondError(c, http.StatusInternalServerError, "PUBLISH_VIDEO_FAILED",
			"视频发布失败", err.Error())
		return
	}

	respondSuccess(c, result, "视频发布成功")
}

// listFeedsHandler 获取Feeds列表
func (s *AppServer) listFeedsHandler(c *gin.Context) {
	result, err := s.xiaohongshuService.ListFeeds(c.Request.Context())
	if err != nil {
		respondError(c, http.StatusInternalServerError, "LIST_FEEDS_FAILED",
			"获取Feeds列表失败", err.Error())
		return
	}

	respondSuccess(c, result, "获取Feeds列表成功")
}

// searchFeedsHandler 搜索Feeds
func (s *AppServer) searchFeedsHandler(c *gin.Context) {
	var keyword string
	var filters xiaohongshu.FilterOption

	switch c.Request.Method {
	case http.MethodPost:
		// 对于POST请求，从JSON中获取keyword
		var searchReq SearchFeedsRequest
		if err := c.ShouldBindJSON(&searchReq); err != nil {
			respondError(c, http.StatusBadRequest, "INVALID_REQUEST",
				"请求参数错误", err.Error())
			return
		}
		keyword = searchReq.Keyword
		filters = searchReq.Filters
	default:
		keyword = c.Query("keyword")
	}

	if keyword == "" {
		respondError(c, http.StatusBadRequest, "MISSING_KEYWORD",
			"缺少关键词参数", "keyword parameter is required")
		return
	}

	result, err := s.xiaohongshuService.SearchFeeds(c.Request.Context(), keyword, filters)
	if err != nil {
		respondError(c, http.StatusInternalServerError, "SEARCH_FEEDS_FAILED",
			"搜索Feeds失败", err.Error())
		return
	}

	respondSuccess(c, result, "搜索Feeds成功")
}

// getFeedDetailHandler 获取Feed详情
func (s *AppServer) getFeedDetailHandler(c *gin.Context) {
	var req FeedDetailRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		respondError(c, http.StatusBadRequest, "INVALID_REQUEST",
			"请求参数错误", err.Error())
		return
	}

	var result *FeedDetailResponse
	var err error

	if req.CommentConfig != nil {
		config := xiaohongshu.CommentLoadConfig{
			ClickMoreReplies:    req.CommentConfig.ClickMoreReplies,
			MaxRepliesThreshold: req.CommentConfig.MaxRepliesThreshold,
			MaxCommentItems:     req.CommentConfig.MaxCommentItems,
			ScrollSpeed:         req.CommentConfig.ScrollSpeed,
		}
		result, err = s.xiaohongshuService.GetFeedDetailWithConfig(c.Request.Context(), req.FeedID, req.XsecToken, req.LoadAllComments, config)
	} else {
		result, err = s.xiaohongshuService.GetFeedDetail(c.Request.Context(), req.FeedID, req.XsecToken, req.LoadAllComments)
	}

	if err != nil {
		respondError(c, http.StatusInternalServerError, "GET_FEED_DETAIL_FAILED",
			"获取Feed详情失败", err.Error())
		return
	}

	respondSuccess(c, result, "获取Feed详情成功")
}

// userProfileHandler 用户主页
func (s *AppServer) userProfileHandler(c *gin.Context) {
	var req UserProfileRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		respondError(c, http.StatusBadRequest, "INVALID_REQUEST",
			"请求参数错误", err.Error())
		return
	}

	result, err := s.xiaohongshuService.UserProfile(c.Request.Context(), req.UserID, req.XsecToken, req.Tab)
	if err != nil {
		respondError(c, http.StatusInternalServerError, "GET_USER_PROFILE_FAILED",
			"获取用户主页失败", err.Error())
		return
	}

	respondSuccess(c, map[string]any{"data": result}, "result.Message")
}

// postCommentHandler 发表评论到Feed
func (s *AppServer) postCommentHandler(c *gin.Context) {
	var req PostCommentRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		respondError(c, http.StatusBadRequest, "INVALID_REQUEST",
			"请求参数错误", err.Error())
		return
	}

	// 发表评论
	result, err := s.xiaohongshuService.PostCommentToFeed(c.Request.Context(), req.FeedID, req.XsecToken, req.Content)
